   368  static bool decodeReturn(cs_struct *ud, MCInst *MI, bpf_internal *bpf)
   369  {
   370          /* Here only handles the BPF_RET class in cBPF */
   371          switch (BPF_RVAL(bpf->op)) {
   372          case BPF_SRC_K:
   373                  MCOperand_CreateImm0(MI, bpf->k);
   374                  return true;
   375          case BPF_SRC_X:
   376                  MCOperand_CreateReg0(MI, BPF_REG_X);
