   255  static bpf_insn op2insn_jmp(unsigned opcode)
   256  {
   257  #define CASE(c) case BPF_JUMP_##c: return BPF_INS_##c
   258          switch (BPF_OP(opcode)) {
   259          case BPF_JUMP_JA:
   260                  return BPF_INS_JMP;
   261          CASE(JEQ);
   262          CASE(JGT);
   263          CASE(JGE);
   264          CASE(JSET);
   265          CASE(JNE);
   266          CASE(JSGT);
   267          CASE(JSGE);
   268          CASE(CALL);
   269          CASE(EXIT);
   270          CASE(JLT);
   271          CASE(JLE);
   272          CASE(JSLT);
   273          CASE(JSLE);
   274          }
   275  #undef CASE
   276
   277          return BPF_INS_INVALID;
