   280  static void update_regs_access(cs_struct *ud, cs_detail *detail,
   281                  bpf_insn insn_id, unsigned int opcode)
   282  {
   283          if (insn_id == BPF_INS_INVALID)
   284                  return;
   285  #define PUSH_READ(r) do { \
   286                  detail->regs_read[detail->regs_read_count] = r; \
   287                  detail->regs_read_count++; \
   288          } while (0)
   289  #define PUSH_WRITE(r) do { \
   290                  detail->regs_write[detail->regs_write_count] = r; \
   291                  detail->regs_write_count++; \
   292          } while (0)
   293          /*
   294           * In eBPF mode, only these instructions have implicit registers access:
   295           * - ld{w,h,b,dw} * // w: r0
   296           * - exit // r: r0
   297           */
   298          if (EBPF_MODE(ud)) {
   299                  switch (insn_id) {
   300                  default:
   301                          break;
   302                  case BPF_INS_LDW:
   303                  case BPF_INS_LDH:
   304                  case BPF_INS_LDB:
   305                  case BPF_INS_LDDW:
   306                          PUSH_WRITE(BPF_REG_R0);
   307                          break;
   308                  case BPF_INS_EXIT:
   309                          PUSH_READ(BPF_REG_R0);
   310                          break;
   311                  }
   312                  return;
   313          }
   314
   315          /* cBPF mode */
   316          switch (BPF_CLASS(opcode)) {
   317          default:
   318                  break;
   319          case BPF_CLASS_LD:
   320                  PUSH_WRITE(BPF_REG_A);
   321                  break;
   322          case BPF_CLASS_LDX:
   323                  PUSH_WRITE(BPF_REG_X);
   324                  break;
   325          case BPF_CLASS_ST:
   326                  PUSH_READ(BPF_REG_A);
   327                  break;
   328          case BPF_CLASS_STX:
   329                  PUSH_READ(BPF_REG_X);
   330                  break;
   331          case BPF_CLASS_ALU:
   332                  PUSH_READ(BPF_REG_A);
   333                  PUSH_WRITE(BPF_REG_A);
   334                  break;
   335          case BPF_CLASS_JMP:
   336                  if (insn_id != BPF_INS_JMP) // except the unconditional jump
   337                          PUSH_READ(BPF_REG_A);
   338                  break;
   339          /* case BPF_CLASS_RET: */
   340          case BPF_CLASS_MISC:
   341                  if (insn_id == BPF_INS_TAX) {
   342                          PUSH_READ(BPF_REG_A);
   343                          PUSH_WRITE(BPF_REG_X);
   344                  }
   345                  else {
   346                          PUSH_READ(BPF_REG_X);
   347                          PUSH_WRITE(BPF_REG_A);
   348                  }
   349                  break;
   350          }
   351  }
